window.MODULES = {"generated":"2026-11-26","modules":[{"id":5681,"name":"Les gilets de sauvetage","assessment":false,"intro":"<p><strong>Les gilets de sauvetage sont à utiliser pour toute évacuation maritime.</strong></p><p>Rappel des tranches d'âge :</p><ul><li>Nourrisson de 0 à 2 ans exclu</li><li>Enfant de 2 ans à 12 ans exclu</li><li>Adulte 12 ans et plus</li></ul>","steps":[{"sid":"48760","title":"Description et utilisation du gilet double chambre sur l'enfant","type":"video","video":"SECU-01-gilet-double-chambre-enfant.mp4","siteVideo":"GILET_DOUBLE.mp4","youtubeId":"XTFfZjT85uI","description":null},{"sid":"48761","title":"Le gilet double chambre est adaptable sur l'enfant et l'adulte","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48763","title":"Description et utilisation du gilet mono chambre sur l'enfant","type":"video","video":"SECU-02-gilet-mono-chambre-enfant.mp4","siteVideo":"GILET_MONO.mp4","youtubeId":"hE73MeAsbwc","description":null},{"sid":"48764","title":"Après avoir mis le gilet sur l'enfant, quelle est l'étape suivante ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Attacher le gilet","correct":false},{"text":"Gonfler le gilet","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48766","title":"Description et utilisation du gilet bébé","type":"video","video":"SECU-03-gilet-bebe.mp4","siteVideo":"GILET_BB.mp4","youtubeId":"1mCWv_V_wyE","description":null},{"sid":"48767","title":"Les gilets peuvent être mis en prévision d'une évacuation terrestre","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48768","title":"Reliez les caractéristiques au gilet correspondant","type":"match","pairs":[{"left":"2 systèmes de percussion semi-automatiques","right":"Double chambre"},{"left":"1 embout buccal","right":"Mono chambre"},{"left":"Cordelette de retenue","right":"Gilet bébé"}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48769","title":"Quel est l'ordre correct pour la mise du gilet sur l'adulte ?","type":"order","items":["Mettre le gilet","Sangler","Ajuster","Gonfler"],"description":null,"explanation":"<p>Le passager adulte gonflera son gilet au seuil de porte lors de l'évacuation de l'appareil.</p>","wasCorrect":true},{"sid":"48770","title":"A quel moment mettre le gilet au nourrisson ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Au début du vol","correct":false},{"text":"Au moment d'évacuer","correct":false},{"text":"Au moment de la préparation cabine","correct":true}],"description":null,"explanation":null,"wasCorrect":true}]},{"id":5682,"name":"Les positions de sécurité","assessment":false,"intro":"<p>Les positions de sécurité sont à adapter en fonction de 3 critères :</p><ul><li>L'espacement entre les sièges</li><li>Le sens de la marche </li><li>La corpulence du passager (enfant, femme enceinte …)</li></ul><p>Il existe 3 positions :</p><ul><li>Groupée face à la marche</li><li>Dressée face à la marche</li><li>Avec bébé</li></ul>","steps":[{"sid":"48718","title":"Les positions de sécurité","type":"video","video":"SECU-04-positions-de-securite.mp4","siteVideo":"POSITIONS.mp4","youtubeId":"n3Ui1Ml46s4","description":null},{"sid":"48719","title":"Les positions sont adaptables en fonction de la corpulence du passager.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48720","title":"Quelle position faites-vous adopter à une femme enceinte ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Dressée","correct":true},{"text":"Groupée","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48721","title":"La ceinture de sécurité doit nécessairement être attachée","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48722","title":"Associer la position adaptée au passager.","type":"match","pairs":[{"left":"Passager de forte corpulence","right":"Position dressée"},{"left":"Adulte avec un nourrisson","right":"Position avec bébé"},{"left":"Passager au premier rang face au cockpit","right":"Position dressée ou groupée"},{"left":"Passager de 80ans en classe economique","right":"Position groupée"}],"description":null,"explanation":null,"wasCorrect":false},{"sid":"48723","title":"Le PNC face à la marche doit adopter la position dressée","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":false}]},{"id":5683,"name":"Les évacuations","assessment":false,"intro":"<p>Toute évacuation doit être menée jusqu'au bout.</p><p>Plusieurs scénarios sont possibles, à vous de l'identifier et vous adapter. </p><p>Différents critères sont à prendre en compte : préparée ou non-préparée, maritime ou terrestre, si maritime avec canot ou toboggan convertible.</p><p>Pour commencer une évacuation on considère que l'avion est immobilisé, les moteurs coupés et l'<strong>ordre d'évacuer est donné par l'équipage de conduite.</strong></p>","steps":[{"sid":"48733","title":"EVACUATIONS - TERRESTRES","type":"video","video":"SECU-05-evacuation-terrestre.mp4","siteVideo":"Evacuation_CCA_AeroSchool.mp4","youtubeId":"L0CrXUe-DfY","description":"<p>Une évacuation préparée a lieu lorsque l'incident s'est passé en vol et que la cabine a pu être préparée à une évacuation. </p><p>(elle peut également être en zone aéroportuaire dans le cadre d'un déroutement vers un aéroport par exemple)</p>"},{"sid":"48734","title":"Remettez le déroulé de cette évacuation dans le bon ordre.","type":"order","items":["Je me détache, je me lève","Je désigne et demande l'assistance de mon PAX requis","Je vérifie les conditions extérieures","Je vérifie l'armement du toboggan"],"description":"<p>EVACUATION TERRESTRE</p>","explanation":null,"wasCorrect":true},{"sid":"48735","title":"Lors d'une évacuation en zone polaire, j'emporte","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Le lot de survie","correct":true},{"text":"Le container de survie","correct":false}],"description":"<p>EVACUATION TERRESTRE</p>","explanation":null,"wasCorrect":true},{"sid":"48736","title":"Les passagers doivent évacuer","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Les bras et jambes pliés","correct":false},{"text":"Les bras pliés contre leur poitrine","correct":false},{"text":"Les bras et jambes tendus en avant","correct":true},{"text":"En courant sur le toboggan","correct":false}],"description":"<p>EVACUATION TERRESTRE</p>","explanation":null,"wasCorrect":true},{"sid":"48737","title":"En zone désertique, que faire après avoir évacué l'avion ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Réunir les passagers dans une zone non dangereuse","correct":true},{"text":"Attendre les secours au pied de l'avion pour être à l'ombre","correct":false}],"description":"<p>EVACUATION TERRESTRE</p>","explanation":"<p>Pour créer de l'ombre il sera possible d'utiliser les toboggans. </p>","wasCorrect":true},{"sid":"48739","title":"Evacuation non-préparée maritime avec canot","type":"video","video":"SECU-06-evacuation-maritime-non-preparee-canot.mp4","siteVideo":"EVAC_CANOT_NP_11-2025.mp4","youtubeId":"B52SYEl1xfc","description":"<p>Lors d'une évacuation NON-PREPAREE, elle se déroulera<strong> OBLIGATOIREMENT </strong>en zone aéroportuaire. </p><p>L'accident a lieu au décollage ou à l'atterrissage. </p>"},{"sid":"48740","title":"Que faut-il faire dans une évacuation maritime avec un canot pour le désolidariser de l’avion ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Soulever la bavette, tirer sur la poignée de désolidarisation, et trancher le filin d'amarrage avec le couteau insubmersible","correct":false},{"text":"Rien, le point de rupture à 180 kg constitue une sécurité","correct":false},{"text":"Trancher le filin d'amarrage avec le couteau insubmersible , un point de rupture de 180kg constitue une sécurité","correct":true},{"text":"Tirer sur la poignée de désolidarisation, et trancher le filin d'amarrage à l’aide du couteau insubmersible","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48741","title":"Quelle est la technique qui permet le gonflage du canot pendant une évacuation maritime ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Ouvrir la porte, et tirer sur la poignée de gonflage en secours","correct":false},{"text":"Ouvrir la porte, lancer le canot, et l’accrocher à un point de structure de l’avion","correct":false},{"text":"Accrocher la porte à un point de structure, lancer le canot, tirer sur le filin","correct":false},{"text":"Accrocher le canot à un point de structure, ouvrir la porte, lancer le canot, tirer sur le filin d'amarrage","correct":true}],"description":"<p>EVACUATION MARITIME AVEC CANOT</p>","explanation":null,"wasCorrect":true},{"sid":"48743","title":"Evacuation préparée maritime avec toboggan convertible","type":"video","video":"SECU-07-evacuation-maritime-preparee-toboggan.mp4","siteVideo":"EVAC_TOBOGGAN_P_11-2025.mp4","youtubeId":"SswNvr8C-Eo","description":null},{"sid":"48744","title":"Lors d'une évacuation maritime vous devez vérifier que le seuil de porte ne soit pas immergé avant de l'ouvrir.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":"<p>EVACUATION MARITIME</p>","explanation":"<p>Si l'eau rentre, refermer la porte et diriger les passagers vers l'issue utilisable la plus proche.</p>","wasCorrect":true},{"sid":"48745","title":"Votre avion vient de rater son décollage à Nice. Il s’est immobilisé dans l’eau, non loin du rivage. Quelle est votre première action ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Faire une annonce aux Pax, « restez assis, détachez votre ceinture, enfilez les gilets sans les gonfler »","correct":false},{"text":"Je me détache, je me lève","correct":true},{"text":"Je me détache, je prends mon gilet je me lève","correct":false},{"text":"J’enfile mon gilet","correct":false}],"description":"<p>EVACUATION MARITIME</p>","explanation":null,"wasCorrect":false},{"sid":"48746","title":"Lors d’une évacuation, le toboggan ne se déploie pas, que faire ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Tirer sur la poignée de gonflage de secours","correct":true},{"text":"Tirer sur la poignée de désolidarisation","correct":false},{"text":"Diriger les passagers vers l’issue utilisable la plus proche","correct":false}],"description":"<p>EVACUATION MARITIME AVEC TOBOGGAN CONVERTIBLE</p>","explanation":null,"wasCorrect":true},{"sid":"48747","title":"Quelle affirmation est correcte concernant un toboggan convertible ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Il n’est pas fait pour la survie en haute mer mais flotte, il se trouve dans le coffre a toboggan de la porte, il faudra vérifier le bon armement du toboggan avant d’ouvrir la porte","correct":false},{"text":"Il est fait pour la survie en haute mer, a des mâts, il se trouve dans le coffre a toboggan de la porte, il faudra vérifier le bon armement du toboggan avant d’ouvrir la porte","correct":true},{"text":"ll est fait pour la survie en haute mer, a des mâts, il se trouve dans un rack a bagage et doit être accroché avant l’ouverture de la porte","correct":false}],"description":"<p>EVACUATION MARITIME AVEC TOBOGGAN CONVERTIBLE</p>","explanation":"<p>Le toboggan convertible est intégré à la porte de l'avion et se déploie lors de l'ouverture de celle-ci s'il est armé.</p>","wasCorrect":true},{"sid":"48748","title":"Lors d'une évacuation maritime, les gilets de sauvetage sont nécessaires.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":"<p>GENERALITES</p>","explanation":"<p>Ils sont même indispensables.</p>","wasCorrect":true},{"sid":"48749","title":"Une évacuation préparée peut être en zone aéroportuaire","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":"<p>GENERALITES</p>","explanation":"<p>Il est tout à fait possible d'avoir une évacuation préparée en zone aéroportuaire car si le problème à lieu non-loin d'un aéroport ils favoriseront un atterrissage/amerrissage dans une zone aménagée.</p>","wasCorrect":true},{"sid":"48750","title":"Quels éléments constituent le briefing d'un passager requis ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Son rôle de service et de remplacement","correct":false},{"text":"Son rôle de protection et d’assistance","correct":true},{"text":"Son rôle de remplacement et d’assistance","correct":false}],"description":"<p>GENERALITES</p>","explanation":null,"wasCorrect":true},{"sid":"48751","title":"Lors d'une évacuation NON-PREPAREE quel matériel de sécurité est à emporter ?","type":"mcq","input":"checkbox","multiple":true,"options":[{"text":"Torche","correct":true},{"text":"Trousse de premiers secours","correct":false},{"text":"Mégaphone","correct":true},{"text":"Balise","correct":false}],"description":"<p>GENERALITES</p>","explanation":"<p>Etant une évacuation non-préparée, elle a obligatoirement lieu en zone aéroportuaire ; de ce fait les secours seront sur place en moins de 3min.</p>","wasCorrect":true},{"sid":"48752","title":"Où vous situez-vous dans l'avion lors de l'évacuation ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Au siège de structure PNC (jump seat)","correct":false},{"text":"Au point de commandement","correct":true}],"description":"<p>GENERALITES</p>","explanation":"<p>Le point de commandement est la poignée de structure située à proximité de l'issue</p>","wasCorrect":true},{"sid":"48753","title":"Reliez la poignée à sa couleur","type":"match","pairs":[{"left":"Poignée de désolidarisation","right":"Blanc"},{"left":"Poignée de gonflage de secours","right":"Rouge"}],"description":"<p>GENERALITES</p>","explanation":"<p>La plupart des éléments de sécurité dans un avion sont de couleur rouge. </p><p><img src=\"media/cropped_pull_to_inflate.jpg\" alt=\"\"></p>","wasCorrect":true},{"sid":"48754","title":"Dans quel type d’évacuation, est-il INUTILE de vérifier sa zone ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Dans l’évacuation en milieu polaire","correct":false},{"text":"Dans l’évacuation maritime non préparée","correct":false},{"text":"Dans l’évacuation mixte","correct":false},{"text":"Aucune","correct":true}],"description":"<p>GENERALITES</p>","explanation":"<p>La vérification du cockpit est obligatoire.</p>","wasCorrect":true},{"sid":"48755","title":"A quoi consiste une préparation cabine ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Aider l'équipage de conduite","correct":false},{"text":"Préparer les passagers à évacuer","correct":false},{"text":"Préparer la cabine, les passagers et les PNC","correct":true}],"description":"<p>GENERALITES</p>","explanation":"<p>Il faudra ranger la cabine (sac, matériel de service…) ; les passagers (gilets, positions…) et les PNC (check liste silencieuse entre autre)</p>","wasCorrect":true},{"sid":"48756","title":"Lors de l'annonce aux passagers, vous leur demandez de gonfler leur gilet immédiatement.","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":"<p>GENERALITES </p>","explanation":"<p>Les passagers devront gonfler leur gilet au seuil de la porte (sauf enfants et nourrissons)</p>","wasCorrect":true},{"sid":"48757","title":"Lorsqu'une évacuation est dirigée, il faut être ferme, dynamique et rapide.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":"<p>GENERALITES</p>","explanation":"<p>N'oublions pas qu'une évacuation doit être menée dans sa totalité en moins de 90 secondes.</p>","wasCorrect":true},{"sid":"48758","title":"Lors d'une évacuation (hors zone aéro) je dois emmener les trousses médicales","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":"<p>trousses médicales = TPS + TMU</p>","wasCorrect":true}]},{"id":5684,"name":"Les moyens de signalisation","assessment":false,"intro":"<p>Les moyens de signalisation sont les différents éléments qu'il faudra à mettre en œuvre pour la survie; ils permettent d'être repérés par les secours.</p><p>Il s'agit :</p><ul><li>balise ADT 406S</li><li>fluorescéine</li><li>miroir</li><li>pyrotechniques (stylo lance fusée et combiné jour/nuit)</li></ul>","steps":[{"sid":"48671","title":"Description de la balise","type":"video","video":"SECU-08-balise-description.mp4","siteVideo":"D_BALISE.mp4","youtubeId":"XYvVM3WYKEo","description":null},{"sid":"48672","title":"Trouvez l'interrupteur et le témoin de fonctionnement de la balise ADT 406S","type":"hotspot","image":"cropped_IMG_1965.jpg","zones":[{"name":"Témoin lumineux et sonore","left":57,"top":49,"width":7,"height":10},{"name":"Interrupteur ON/OFF/ARMED","left":67,"top":52,"width":7,"height":11}],"description":null,"explanation":"<p>Attention !!! Lorsque vous manipulerez l'interrupteur de la balise il faudra le <i><strong><u>SOULEVER</u></strong></i> pour passer d'une position à une autre.</p>"},{"sid":"48673","title":"Relier les fréquences d'émissions à leur nom.","type":"match","pairs":[{"left":"121,5 MHz","right":"Civile"},{"left":"243 MHz","right":"Militaire"},{"left":"406 MHz","right":"Satellitaire"}],"description":"<p>BALISE ADT 406S</p>","explanation":null,"wasCorrect":true},{"sid":"48674","title":"Utilisation de la balise en maritime et terrestre","type":"video","video":"SECU-09-balise-utilisation-maritime-terrestre.mp4","siteVideo":"U_BALISE_MT.mp4","youtubeId":"he3XcKNZ4_g","description":"<p>Lors de l'examen on peut vous demander l'utilisation en maritime, en terrestre ou les deux.</p>"},{"sid":"48675","title":"La balise de détresse est la première mise en œuvre après l'ancre flottante","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48676","title":"La balise a une phase d'auto-test lorsqu'elle est utilisée en","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Terrestre","correct":true},{"text":"Maritime","correct":false}],"description":"<p>BALISE ADT 406S</p>","explanation":"<p>En terrestre :</p><ul><li>Phase d'auto-test de 20 sec</li><li>Phase d'attente de 30 sec</li><li>Phase d'émission </li></ul>","wasCorrect":true},{"sid":"48678","title":"Comment différencier un pain/bloc d'un sachet de fluorescéine ?","type":"match","pairs":[{"left":"Pain (ou bloc)","right":"Dur au toucher"},{"left":"Sachet","right":"Mou au toucher"}],"description":null,"explanation":"<p>Le bloc (pain) est dur au toucher, il se dissoudra par principe d'érosion.</p><p>Le sachet est mou, la poudre est volatile.</p>","wasCorrect":true},{"sid":"48679","title":"Lors de l'utilisation de fluorescéine","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Utiliser tous les sachets en même temps","correct":false},{"text":"Utiliser les sachets les uns après les autres","correct":true}],"description":"<p>FLUORESCEINE</p>","explanation":null,"wasCorrect":false},{"sid":"48681","title":"Le miroir grand modèle a une portée de 5 km","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":"<p>MIROIR</p>","explanation":"<p>Grand modèle 15 km (miroir que vous utiliserez)</p><p>Petit modèle 5 km </p>","wasCorrect":true},{"sid":"48682","title":"Tout le monde peut se servir du miroir lors de la survie.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":"<p>MIROIR</p>","explanation":"<p>PNC et passagers.</p>","wasCorrect":true},{"sid":"48686","title":"Description du stylo lance fusée","type":"video","video":"SECU-10-stylo-lance-fusee-description.mp4","siteVideo":"D_STYLO.mp4","youtubeId":"x5g24cS6vIM","description":null},{"sid":"48687","title":"Utilisation du stylo lance fusée","type":"video","video":"SECU-11-stylo-lance-fusee-utilisation.mp4","siteVideo":"STYLO_2025_OK.mp4","description":null},{"sid":"48688","title":"Dans quelle position dois-je me mettre pour utiliser un moyen pyrotechnique de signalisation en milieu maritime ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Passagers et vent dans le dos, assis sur le tore de l'embarcation, bras à 45° à l'extérieur.","correct":false},{"text":"Passagers et vent dans le dos, à genoux dans l'embarcation, bras à 45° à l'extérieur.","correct":true},{"text":"Passagers et vent dans le dos, debout dans l'embarcation, bras à 45° à l'extérieur.","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48690","title":"Des bandes sol/air sont la même chose que des bandes air/sol","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":"<p>BANDES SOL/AIR</p>","explanation":"<p>Le nom indique bien la provenance et la destination du message.</p><p>Sol → Air </p><p>Air → Sol (banderoles tractées par les avions)</p>","wasCorrect":false},{"sid":"48691","title":"Associer les moyens de signalisation à leur précaution d'utilisation.","type":"match","pairs":[{"left":"Le stylo lance fusée","right":"Secours vus et/ou entendus et proches"},{"left":"Sky Blazer","right":"Secours vus et/ou entendus"},{"left":"Le miroir","right":"Aucun secours en vue"}],"description":null,"explanation":"<p>Les précautions sont <strong>INDISPENSABLES</strong> à l'utilisation des moyens pyrotechniques (vous devrez donc les annoncer en tout premier lieu)</p>","wasCorrect":true},{"sid":"48692","title":"Quelle est LA précaution pour utiliser un moyen pyrotechnique de signalisation ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Passagers et vent dans le dos","correct":false},{"text":"Les secours sont vus et/ou entendus","correct":true},{"text":"Je m'équipe de gants polaires","correct":false}],"description":null,"explanation":null,"wasCorrect":false},{"sid":"48694","title":"Pour utiliser le combiné jour nuit je dois casser mon poignet pendant la combustion","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":"<p>Cela évitera de vous bruler</p>","wasCorrect":true},{"sid":"48695","title":"Pour utiliser le stylo lance fusée, je vise le ciel, stylo à la verticale","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true}]},{"id":5685,"name":"Sky Blazer","assessment":false,"intro":"","steps":[{"sid":"49325","title":"Description SKY BLAZER","type":"video","video":"SECU-12-sky-blazer-description.mp4","siteVideo":"DESCR_skyblazer.mp4","description":null},{"sid":"49323","title":"Le Sky Blazer est utilisable :","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Uniquement de jour","correct":false},{"text":"Uniquement de nuit","correct":false},{"text":"De jour et de nuit","correct":true},{"text":"Uniquement par temps clair","correct":false}],"description":null,"explanation":null,"wasCorrect":false},{"sid":"49324","title":"Quelle portée de hauteur est indiquée pour le Sky Blazer ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"34 mètres","correct":false},{"text":"134 mètres","correct":true},{"text":"314 mètres","correct":false},{"text":"1 340 mètres","correct":false}],"description":null,"explanation":null,"wasCorrect":false},{"sid":"49326","title":"Utilisation SKY BLAZER","type":"video","video":"SECU-13-sky-blazer-utilisation.mp4","siteVideo":"UTIL_SKY_BLAZER.mp4","description":null},{"sid":"49329","title":"En situation terrestre, quel type d’endroit faut-il choisir ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Un endroit couvert","correct":false},{"text":"Un endroit dégagé et en hauteur","correct":true},{"text":"Un endroit bas et abrité","correct":false},{"text":"Un endroit proche des passagers","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49331","title":"À quel angle faut-il tenir le bras pour lancer la fusée ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"À 15° au-dessus de la tête","correct":false},{"text":"À 30° au-dessus de la tête","correct":false},{"text":"À 45° au-dessus de la tête","correct":true},{"text":"À 90° au-dessus de la tête","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49332","title":"Comment est qualifiée la manipulation de cet artifice dans le manuel ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Sans danger si elle est rapide","correct":false},{"text":"Extrêmement dangereuse","correct":true},{"text":"Réservée à une utilisation intérieure","correct":false},{"text":"Sans risque de brûlure","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49333","title":"Quelle est la visibilité indiquée du Sky Blazer par temps clair ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Jusqu’à 3,2 km","correct":false},{"text":"Jusqu’à 13,4 km","correct":false},{"text":"Jusqu’à 32 km","correct":true},{"text":"Jusqu’à 134 km","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49334","title":"Dans quelle position faut-il tenir fermement le manchon orange ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Horizontale","correct":false},{"text":"Verticale","correct":true},{"text":"À 45° vers le bas","correct":false},{"text":"À l’envers","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49337","title":"Qu'est-ce qu'est le CANDELA ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"une unité d'intensité sonore","correct":false},{"text":"une unité d'intensité lumineuse","correct":true},{"text":"une unité de puissance","correct":false}],"description":null,"explanation":null,"wasCorrect":true}]},{"id":5686,"name":"Les apparaux","assessment":false,"intro":"<p>Les apparaux sont du matériel contenu dans le lot ou kit de survie qui, une fois mis en œuvre nous aideront à la survie. </p><p>Nous trouverons ci-après :</p><ul><li>couteau / tranchet</li><li>ancre flottante</li><li>haussière et anneau</li><li>pompe à main</li><li>écope</li><li>éponge</li><li>sac récupérateur d'eau de pluie</li><li>nécessaire de réparation (cônes et coupelles)</li></ul>","steps":[{"sid":"48772","title":"Les apparaux","type":"video","video":"SECU-14-apparaux-partie-1.mp4","siteVideo":"APPARAUX_1.mp4","description":"<p>PREMIERE PARTIE</p>"},{"sid":"48773","title":"Les apparaux","type":"video","video":"SECU-15-apparaux-partie-2.mp4","siteVideo":"APPARAUX_2.mp4","description":"<p>DEUXIEME PARTIE</p>"},{"sid":"48774","title":"Les cônes d'obturation de trous","type":"video","video":"SECU-16-cones-obturation-trous.mp4","siteVideo":"CONES.mp4","description":null},{"sid":"48775","title":"Les coupelles d'obturation de trous","type":"video","video":"SECU-17-coupelles-obturation-trous.mp4","siteVideo":"COUPELLES.mp4","description":null},{"sid":"48776","title":"Quels sont les apparaux que vous trouvez directement sur le tore de l'embarcation ?","type":"mcq","input":"checkbox","multiple":true,"options":[{"text":"ancre flottante","correct":true},{"text":"kit de réparation","correct":false},{"text":"pompe à main","correct":false},{"text":"haussière et anneau","correct":true},{"text":"sac récupérateur d'eau de pluie","correct":false},{"text":"écope","correct":false},{"text":"couteau insubmersible","correct":true}],"description":null,"explanation":"<p>Seuls le couteau, la haussière et l'ancre flottante se trouve sur le tore. Se sont les premiers éléments dont les PNC auront expressément besoin après avoir rejoint l'embarcation.</p>","wasCorrect":false},{"sid":"48777","title":"Dans l'organisation de la survie, mettre en œuvre l'ancre flottante avant l'utilisation de la haussière.","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":null,"explanation":"<p>Il faut en premier lieu sortir les passagers de l'eau grâce à la haussière.</p>","wasCorrect":false},{"sid":"48778","title":"En maritime, les éléments (autres que ceux présents sur le tore de l'embarcation) sont contenus dans :","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"le lot de survie","correct":false},{"text":"le container de survie","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48779","title":"Reliez le matériel à son utilisation.","type":"match","pairs":[{"left":"Cône de réparation","right":"Trou"},{"left":"Coupelles de réparation","right":"Déchirure"}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48780","title":"La pompe à main peut servir à écoper.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48781","title":"A quoi sert l'ancre flottante ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Eviter que l'embarcation coule","correct":false},{"text":"Limiter la dérive due au vent","correct":true},{"text":"Limiter la dérive due aux courants","correct":false}],"description":null,"explanation":null,"wasCorrect":true}]},{"id":5687,"name":"L'oxygène","assessment":false,"intro":"<p>Il existe plusieurs formes d'oxygène à bord d'un avion :</p><ul><li>bouteille d'oxygène</li><li>cagoule de protection respiratoire</li><li>masque passager</li><li>masque full face pour l'équipage de conduite</li></ul><p>Plusieurs types d'oxygènes :</p><ul><li>premiers secours</li><li>protection respiratoire</li><li>subsistance</li></ul><p>3 exercices sont requis : </p><ul><li>description</li><li>prévol</li><li>utilisation sur adulte et/ou nourrisson</li></ul>","steps":[{"sid":"49335","title":"Description Bouteille 02 - AVOX","type":"video","video":"SECU-18-oxygene-avox-description.mp4","siteVideo":"copy_3A139581-16A9-4391-8FE7-0771447EAA7A_5285.mp4","description":null},{"sid":"48699","title":"Relier la durée d'administration maximum au débit correspondant.","type":"match","pairs":[{"left":"4L/min","right":"1h15 ou 75min"},{"left":"2L/min","right":"2h30 ou 150min"}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49336","title":"Prévol Bouteille 02 - AVOX","type":"video","video":"SECU-19-oxygene-avox-prevol.mp4","siteVideo":"PREVOL_O2_AVOX.mp4","description":null},{"sid":"48701","title":"Lors de la prévol je vérifie le bouchon obturateur sur la prise baïonnette","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49350","title":"ADMINISTRATION ADULTE","type":"video","video":"SECU-20-oxygene-administration-adulte.mp4","siteVideo":"ADM_ADT_O2.mp4","description":null},{"sid":"49351","title":"ADMINISTRATION BEBE O2","type":"video","video":"SECU-21-oxygene-administration-bebe.mp4","siteVideo":"ADM_BEBE_O2.mp4","description":null},{"sid":"48703","title":"Quelles sont les grandes étapes de l'administration d'oxygène de premier secours sur un passager adulte.","type":"order","items":["Précautions d'utilisation (prévenir l'équipage de conduite, périmètre de sécurité, enlever les corps gras)","S'équiper de la bouteille d'oxygène et brancher le masque","Tourner le sélecteur sur le débit souhaité","Vérifier que l'oxygène passe bien grace au témoin vert qui se gonfle","Noter l'heure TU","Positionner le masque sur le visage du passager et vérifier qu'il respire correctement","Sécuriser la bouteille","Surveiller le passager et la bouteille pendant toute l'administration","Se rééquiper de la bouteille d'oxygène","Enlever le masque en faisant attention au risque de malaise","Fermer la bouteille en tournant le sélecteur et noter l'heure TU","Ranger le matériel et prévenir l'équipage de conduite que la procédure est terminée"],"description":null,"explanation":null,"wasCorrect":false},{"sid":"48715","title":"Où puis-je laisser EN PRIORITE la bouteille d'O2 lors de l'administration à un adulte et que j'ai une tâche de sécurité à réaliser ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Sur le siège d'à coté s'il est libre","correct":false},{"text":"Sous le siège bien attachée à la barre de maintien","correct":true},{"text":"Je la confie au passager d'à coté","correct":false}],"description":null,"explanation":"<p>Je priorise une sécurisation du matériel hors d'atteinte des passagers. Et en cas de turbulences, si elle se décroche, elle fera moins de dégâts sous le siège que sur un siège passager.</p>","wasCorrect":false},{"sid":"48705","title":"Lors de l'administration d'oxygène sur un bébé, je ...","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Ventile car le masque est trop grand pour le visage du bébé.","correct":true},{"text":"Je pose le masque et l'ajuste","correct":false}],"description":null,"explanation":"<p>En hôpital ils administrent de l'oxygène à un bébé à un débit de 15L/min.</p><p>Ventiler permet de ne pas poser le masque car il est adapté à l'adulte et donc d'éviter les yeux du bébé, ce qui pourrait lui brûler la cornée. </p>","wasCorrect":true},{"sid":"48707","title":"Description de la cagoule","type":"video","video":"SECU-22-cagoule-description.mp4","siteVideo":"D_CAGOULE.mp4","description":null},{"sid":"48708","title":"Jusqu'à quelle altitude est certifiée la cagoule pour durer 15 min ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"7 000 m","correct":false},{"text":"2 500 m","correct":false},{"text":"25 000 ft","correct":true},{"text":"70 000 ft","correct":false}],"description":null,"explanation":"<p>25000 ft = 7600 m</p>","wasCorrect":true},{"sid":"48709","title":"Quel élément de la cagoule lui donne son effet \"poumon\" ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Les cartouches filtrantes absorbant le CO2","correct":true},{"text":"La palette de déclenchement","correct":false},{"text":"La soupape de surpression","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48710","title":"Prévol de la cagoule","type":"video","video":"SECU-23-cagoule-prevol.mp4","siteVideo":"P_CAGOULE.mp4","description":null},{"sid":"48711","title":"Lors de la prévol de la cagoule, il faut sortir la cagoule de sa boite.","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":null,"explanation":"<p>Surtout pas ! Cela briserai le scellé.</p>","wasCorrect":true},{"sid":"48712","title":"Utilisation de la cagoule","type":"video","video":"SECU-24-cagoule-utilisation.mp4","siteVideo":"Cagoule.mp4","description":null},{"sid":"48713","title":"Pour mettre la cagoule, je l'enfile :","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"de l'avant vers l'arrière","correct":false},{"text":"de l'arrière vers l'avant","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48714","title":"Une fois la cagoule mise, vérifier que la membrane phonique est bien face à la bouche et les cheveux rentrés.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48716","title":"Au bout de combien MAXIMUM doit-on retirer la cagoule ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"17 min","correct":false},{"text":"15 min","correct":true},{"text":"20 min","correct":false},{"text":"10 min","correct":false}],"description":null,"explanation":null,"wasCorrect":true}]},{"id":5688,"name":"Les extincteurs","assessment":false,"intro":"<p>Il existe 4 types d'extincteurs :</p><ul><li>H2O</li><li>P3 Hafex</li><li>Halon</li><li>Fixe / de poubelle de toilette / de structure</li></ul><p>3 exercices sont requis : </p><ul><li>description</li><li>prévol</li><li>utilisation</li></ul><p>Présentation de l'exercice complet du Feu-Fumée.</p>","steps":[{"sid":"48783","title":"Description extincteur H2O","type":"video","video":"SECU-25-extincteur-h2o-description.mp4","siteVideo":"D_H2O.mp4","description":null},{"sid":"48784","title":"Retrouver la poignée de percussion de l'extincteur H20.","type":"hotspot","image":"cropped_extincteur_H2O_1.jpg","zones":[{"name":"poignée de percussion","left":4,"top":44,"width":48,"height":24}],"description":null,"explanation":null},{"sid":"48785","title":"Prévol extincteur H2O","type":"video","video":"SECU-26-extincteur-h2o-prevol.mp4","siteVideo":"P_H2O.mp4","description":null},{"sid":"48786","title":"Utilisation extincteur H2O","type":"video","video":"SECU-27-extincteur-h2o-utilisation.mp4","siteVideo":"U_H2O.mp4","description":null},{"sid":"48787","title":"Quelle est la précaution à prendre avec l'extincteur H2O ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"S'équiper d'une cagoule de protection respiratoire","correct":false},{"text":"Ne pas toucher le diffuseur et la base","correct":false},{"text":"Accord de l'équipage de conduite","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48789","title":"Description P3 Hafex","type":"video","video":"SECU-28-extincteur-p3-hafex-description.mp4","siteVideo":"description_Hafex.mp4","description":null},{"sid":"48790","title":"Retrouver la goupille de l'extincteur P3 Hafex","type":"hotspot","image":"cropped_photo_hafex_p3.jpg","zones":[{"name":"Goupille","left":52,"top":40,"width":20,"height":18}],"description":null,"explanation":null},{"sid":"48791","title":"Prévol extincteur P3 Hafex","type":"video","video":"SECU-29-extincteur-p3-hafex-prevol.mp4","siteVideo":"prevol_p3.mp4","description":null},{"sid":"48792","title":"Utilisation extincteur P3 HAFEX","type":"video","video":"SECU-30-extincteur-p3-hafex-utilisation.mp4","siteVideo":"5429b7e9-ded0-4525-9177-7d5d5d776e88.mp4","description":null},{"sid":"48793","title":"Quelle est la précaution à prendre avec l'extincteur P3 Hafex ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Accord de l'équipage de conduite","correct":false},{"text":"S'équiper d'une cagoule de protection respiratoire","correct":true},{"text":"Ne pas toucher le diffuseur et la base","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48801","title":"Description extincteur fixe","type":"video","video":"SECU-31-extincteur-fixe-description.mp4","siteVideo":"FIXE_D.mp4","description":null},{"sid":"48802","title":"Prévol extincteur fixe","type":"video","video":"SECU-32-extincteur-fixe-prevol.mp4","siteVideo":"FIXE_P.mp4","description":null},{"sid":"48803","title":"Pourquoi vérifier la bonne étanchéité du compartiment poubelle lors de la prévol de l'extincteur fixe ?","type":"mcq","input":"checkbox","multiple":true,"options":[{"text":"Pour contenir les flammes","correct":true},{"text":"Pour contenir la fumée","correct":false},{"text":"Efficacité du halon","correct":true},{"text":"Pour contenir la chaleur","correct":true}],"description":"<p>Plusieurs réponses possibles</p>","explanation":"<ul><li>Contenir la chaleur afin que l'extincteur se déclenche à environ 80°</li><li>Contenir les flammes pour éviter que l'avion prenne feu</li><li>Contenir la fumée n'est pas indispensable, car le détecteur de fumée alerterai les PNC</li></ul>","wasCorrect":false},{"sid":"48804","title":"LE \"FEU-FUMEE\"","type":"video","video":"SECU-33-exercice-feu-fumee.mp4","siteVideo":"Exercice_Feu_Fumée__final_.mp4","description":"<p>L'exercice du feu-fumée est incontournable pour les épreuves sécurité pratique.</p><p>Cette vidéo vous présente le rendu souhaité. Vous aurez bien entendu un entrainement complet lors de votre formation pour cet exercice.</p>"},{"sid":"48805","title":"A quel moment dégoupillez-vous votre extincteur ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Après avoir pris les précautions nécessaires","correct":true},{"text":"Après s'être positionné devant le feu","correct":false}],"description":"<p>PROCEDURE FEU FICTIF - UTILISATION</p>","explanation":null,"wasCorrect":true},{"sid":"48806","title":"Relier chaque extincteur à sa distance d'action.","type":"match","pairs":[{"left":"H2O","right":"1m"},{"left":"P3 HAFEX","right":"1,5m - 2m"}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48807","title":"Lors de la prévol de l'extincteur fixe, le PNC doit vérifier l'embout des buses.","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":null,"explanation":"<p>C'est à la maintenance de vérifier l'embout des buses d'éjection des extincteurs fixes.</p>","wasCorrect":false},{"sid":"48808","title":"Relier chaque extincteur à sa durée d'action.","type":"match","pairs":[{"left":"H2O","right":"30 sec"},{"left":"P3 Hafex","right":"9 à 10 sec"},{"left":"FIXE","right":"3 à 5 sec"}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48809","title":"A quelle distance se tenir du feu avec l'extincteur P3 Hafex ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"0.50m à 1m","correct":false},{"text":"1m à 1.5m","correct":false},{"text":"1.50m à 2m","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48810","title":"Reliez chaque extincteur à sa distance du foyer","type":"match","pairs":[{"left":"P3 Hafex","right":"1.5 à 2m"},{"left":"H2O","right":"1m"}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48811","title":"Que contient l'extincteur H2O ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"2L d'eau","correct":false},{"text":"2L de glycol","correct":false},{"text":"2L d'eau et de glycol","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48812","title":"Vous avez un feu dans un four (électrique), quel extincteur il ne faut pas utiliser ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"H2O","correct":true},{"text":"HALON","correct":false},{"text":"P3 HAFEX","correct":false}],"description":null,"explanation":"<p>Je favorise l'extincteur au Halon car c'est le plus rapide MAIS attention aux PASSAGERS ! Bien réaliser le périmètre de sécurité (même dans le galley). </p><p>Vous auriez pu aussi choisir le Hafex.</p><p>Surtout pas le H2O car contient de l'eau, ce qui n'est pas compatible avec de l'électricité.</p>","wasCorrect":true}]},{"id":5689,"name":"La hache et le pied de biche","assessment":false,"intro":"<p>La hache et le pied de biche sont à disposition des PNC en cas de nécessité, il faudra nécessairement l'accord de l'équipage de conduite pour les utiliser.</p><p>3 exercices sont requis : </p><ul><li>description</li><li>prévol</li><li>utilisation </li></ul>","steps":[{"sid":"48725","title":"Descriptions","type":"video","video":"SECU-34-hache-pied-de-biche-description.mp4","siteVideo":"HACHE-PDB_D.mp4","description":null},{"sid":"48726","title":"Prévols","type":"video","video":"SECU-35-hache-pied-de-biche-prevol.mp4","siteVideo":"HACHE-PDB_P.mp4","description":null},{"sid":"48727","title":"Il est indispensable d'avoir l'accord de l'équipage de conduite pour utiliser la hache.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48728","title":"Jusqu'à quelle mesure le manche de la hache est isolant ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"2000 Watts","correct":false},{"text":"2000 Ampères","correct":false},{"text":"2000 Volts","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48729","title":"Lors de la prévol de la hache, vous devez enlever la housse en cuir plombée.","type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}],"description":null,"explanation":"<p>Surtout pas ! Le matériel ne serait alors plus conforme.</p>","wasCorrect":true},{"sid":"48730","title":"Remettre dans l'ordre la prévol du pied de biche.","type":"order","items":["Présence conforme au plan d'armement","Bon état général, à l'abri du regard des passagers","Contrôle du système d'arrimage sur son support","Prévol terminée"],"description":null,"explanation":"<p>Vous avez ici les 4 vérifications obligatoires d'une prévol.</p>","wasCorrect":true},{"sid":"48731","title":"Vous suspectez un feu et souhaitez investiguer, vous préférez prendre :","type":"mcq","input":"radio","multiple":false,"options":[{"text":"La hache","correct":true},{"text":"Le pied de biche","correct":false}],"description":null,"explanation":"<p>La hache car elle a un manche isolant jusqu'à 2000V</p>","wasCorrect":true}]},{"id":5690,"name":"Le mégaphone","assessment":false,"intro":"<p>3 exercices sont requis : </p><ul><li>description</li><li>prévol</li><li>utilisation</li></ul>","steps":[{"sid":"48815","title":"Description du mégaphone","type":"video","video":"SECU-36-megaphone-description.mp4","siteVideo":"D_MEGAPHONE.mp4","description":null},{"sid":"48816","title":"Retrouver le nom des éléments composant le mégaphone.","type":"hotspot","image":"cropped_mega.jpg","zones":[{"name":"Micro","left":8,"top":54,"width":11,"height":24},{"name":"Poignée","left":39,"top":5,"width":16,"height":40},{"name":"Bouton ON/OFF","left":51,"top":24,"width":7,"height":14},{"name":"Sangle","left":52,"top":38,"width":24,"height":45},{"name":"Pavillon","left":71,"top":36,"width":18,"height":54}],"description":null,"explanation":null},{"sid":"48817","title":"Prévol du mégaphone","type":"video","video":"SECU-37-megaphone-prevol.mp4","siteVideo":"P_MEGAPHONE.mp4","description":null},{"sid":"48818","title":"Le mégaphone a une portée de 1km.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":"<p>1 km = 1000 m</p>","wasCorrect":true},{"sid":"48819","title":"Il faut toujours sécuriser le mégaphone sur soi lorsqu'on le manipule.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48820","title":"Quels éléments vérifiez-vous lors de la prévol du mégaphone ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Que la sangle soit en bon état et le pavillon non fissuré","correct":false},{"text":"La poignée, le bouton, le diffuseur, le micro, la sangle","correct":false},{"text":"La pavillon, le micro, la sangle, le bouton, la poignée","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48821","title":"Quand utiliser le mégaphone ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Uniquement à l'intérieur de l'avion","correct":false},{"text":"A l'intérieur comme à l'extérieur de l'avion","correct":true},{"text":"Uniquement à l'extérieur de l'avion","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48822","title":"Lors de l'utilisation du mégaphone, il faut parler fort.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":"<p>Plus on parle fort plus le son aura de la portée.</p>","wasCorrect":true}]},{"id":5691,"name":"Système de détection de fumée","assessment":false,"intro":"<p>Le système de détection de fumées dans une toilette.</p>","steps":[{"sid":"48824","title":"Description du panneau de contrôle","type":"video","video":"SECU-38-detection-fumee-panneau-description.mp4","siteVideo":"D_PDC.mp4","description":null},{"sid":"48825","title":"Où se situe le panneau de contrôle ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Dans le galley","correct":true},{"text":"Au cockpit","correct":false},{"text":"Dans les toielttes","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48826","title":"Prévol du panneau de contrôle","type":"video","video":"SECU-39-detection-fumee-panneau-prevol.mp4","siteVideo":"P_PDC.mp4","description":null},{"sid":"48827","title":"Procédure de détection de fumée","type":"video","video":"SECU-40-detection-fumee-procedure.mp4","siteVideo":"PROC_DETEC_FUMEE.mp4","description":"<p>La procédure est <strong>uniquement</strong> liée à l'utilisation suite à une détection de fumée dans une toilette (il n'y a pas toujours un feu : passager qui fume).</p><p>L'extinction d'un feu est une autre procédure : utilisation de l'extincteur.</p>"},{"sid":"48828","title":"Le panneau de contrôle est relié au détecteur de fumée de chaque toilette.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48829","title":"Lors d'une détection de fumée où se situent les alarmes visuelles ?","type":"mcq","input":"checkbox","multiple":true,"options":[{"text":"Dans la toilette concernée","correct":false},{"text":"Au-dessus et à l'extérieur de la toilette concernée","correct":true},{"text":"Au cockpit","correct":true},{"text":"Sur le panneau de contrôle","correct":true},{"text":"Dans la cabine","correct":true}],"description":"<p>Plusieurs réponses attendues.</p>","explanation":"<p><img src=\"media/cropped_TEMOIN.jpg\" alt=\"\"></p>","wasCorrect":false},{"sid":"48830","title":"Lors d'une détection de fumée où se situent les alarmes sonores ?","type":"mcq","input":"checkbox","multiple":true,"options":[{"text":"Dans la toilette concernée","correct":false},{"text":"Au cockpit","correct":true},{"text":"Sur le panneau de contrôle","correct":true},{"text":"Dans la cabine","correct":true}],"description":"<p>Plusieurs réponses attendues.</p>","explanation":null,"wasCorrect":true},{"sid":"48831","title":"La prévol du panneau de contrôle est la seule prévol en commun avec l'équipage de conduite.","type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":"<p>Il faudra nécessairement l'accord de l'équipage de conduite pour déclencher une alarme liée à la sécurité.</p>","wasCorrect":false},{"sid":"48832","title":"Remettre dans l'ordre les actions à mener pour la prévol du panneau de contrôle.","type":"order","items":["Appuyer sur le bouton TEST","Appuyer sur le bouton HORN OFF","Appuyer sur le bouton RESET"],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48833","title":"Relier les boutons du panneau de contrôle à leur action respective.","type":"match","pairs":[{"left":"HORN OFF","right":"Arrêter l'alarme sonore"},{"left":"TEST","right":"Déclencher les alarmes visuelles et sonores"},{"left":"RESET","right":"Réinitialiser le système"}],"description":null,"explanation":"<p>Les actions “TEST” et “RESET” doivent être menées avec l'accord de l'équipage de conduite.</p>","wasCorrect":true},{"sid":"48834","title":"Qu'est-ce que le principe de ionisation ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Détection des particules de fumée","correct":true},{"text":"Détection de la chaleur","correct":false},{"text":"Détection de la lumière émise par les flammes","correct":false}],"description":null,"explanation":null,"wasCorrect":false},{"sid":"48835","title":"Retrouver le buzzer","type":"hotspot","image":"cropped_pano_contr.jpg","zones":[{"name":"Buzzer","left":30,"top":20,"width":15,"height":20}],"description":null,"explanation":null}]},{"id":5692,"name":"Test de validation final SCU","assessment":true,"intro":"<p>VOUS DEVEZ OBTENU 90% POUR ENTRER EN FORMATION</p>","steps":[{"sid":"48851","title":"16. Je viens de demander l’autorisation à l'équipage de conduite d’utiliser le pied de biche dans une toilette pour chercher l’origine d’un feu. Quelle sera ma prochaine action ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Je me muni d'un extincteur + cagoule","correct":true},{"text":"Je fais déplacer les passagers à proximité","correct":false},{"text":"Je prends garde aux câbles, fils électriques et tuyauteries","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49033","title":"198. Combien de temps dure la balise lumineuse du gilet de sauvetage ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"12h","correct":false},{"text":"24h","correct":true},{"text":"48h","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48958","title":"123. Je sors de la cabine enfumée :","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"J’éteins les feux","correct":false},{"text":"Je m’en vais","correct":false},{"text":"Je dégoupille","correct":true},{"text":"J’enlève ma cagoule","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48934","title":"99. Où se trouve la poignée de gonflage de secours ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Sur la porte de l'avion","correct":false},{"text":"Au niveau du seuil de la porte","correct":true},{"text":"A coté du siège PNC","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48892","title":"57. Que faut-il faire dans une évacuation maritime avec un canot pour le désolidariser de l’avion ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Soulever la bavette, tirer sur la poignée de désolidarisation, et trancher le filin d'amarrage avec le couteau insubmersible","correct":false},{"text":"Tirer sur la poignée de désolidarisation, et trancher le filin d'amarrage à l’aide du couteau insubmersible","correct":false},{"text":"Trancher le filin d'amarrage avec le couteau insubmersible , un point de rupture de 180kg constitue une sécurité","correct":true},{"text":"Rien, le point de rupture à 180 kg constitue une sécurité","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48961","title":"126. Le contrôle du système d'arrimage sur son support est un élément de la prévol du pied de biche","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48873","title":"38. A propos de l’utilisation du gilet double chambre adulte/enfant sur un adulte, quel est l’ordre à respecter ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Passer le gilet autour du cou. Gonfler le gilet, si non gonflage utiliser l’embout buccal après dévissage partiel de la cartouche de Co2 défaillante. Passer les sangles autour de la taille, les attacher sur le devant.","correct":false},{"text":"Passer le gilet autour du cou, passer les sangles autour de la taille et les attacher sur le devant. Gonfler le gilet, si non gonflage utiliser l’embout buccal après dévissage partiel de la cartouche de Co2 défaillante","correct":true}],"description":null,"explanation":null,"wasCorrect":false},{"sid":"49029","title":"194. Où se trouve la poignée de désolidarisation ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Au seuil de porte","correct":false},{"text":"Dans le toboggan convertible","correct":false},{"text":"Sous le rabat","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48991","title":"156. Qu'emportez-vous à la fin d'une évacuation (terrestre ou maritime) en zone aéroportuaire ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"La balise, le mégaphone, la trousse de 1er secours, la lampe torche","correct":false},{"text":"La lampe torche, le mégaphone","correct":true},{"text":"Rien","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49012","title":"177. L’éponge permet d’affiner le séchage du fond du canot en survie maritime, mais aussi","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"D’enlever le talc sur son toit","correct":true},{"text":"Récupérer la sueur pour la boire","correct":false},{"text":"Les 2 réponses sont correctes","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48948","title":"113. Où se trouve le couteau insubmersible sur un canot ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Sur le tore inférieur","correct":false},{"text":"Sur le tore supérieur","correct":false},{"text":"Sur le tore supérieur ou le mât central","correct":true},{"text":"Sur le mât central","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48870","title":"35. Pour quelle raison doit-on couper l’alarme sonore lors d’une détection de feu de toilette ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Ne pas effrayer les PAX","correct":false},{"text":"Prévenir l'équipage de conduite qu’on prend en charge le problème","correct":false},{"text":"Afin d’entendre si une autre alarme se déclenche","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48995","title":"160. Quelle est la portée de la fusée (du stylo lance fusée) ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"300 m","correct":false},{"text":"30 m","correct":true},{"text":"3 m","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"49031","title":"196. Quels éléments constituent le stylo lance fusée ? Choisissez la ou les bonnes réponses.","type":"mcq","input":"checkbox","multiple":true,"options":[{"text":"Un percuteur","correct":true},{"text":"Un canon d’armement","correct":false},{"text":"Un cran de sûreté","correct":true},{"text":"Un cran d’armement","correct":true}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48950","title":"115. Où trouver les codes OACI pour utiliser les bandes Sol/Air ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Dans la trousse de premiers secours","correct":false},{"text":"Dans la trousse médicale d’urgence","correct":false},{"text":"Sur le coté blanc des bandes","correct":true},{"text":"Sur le coté rouge des bandes","correct":false}],"description":"<p>1 seule réponse est attendue</p>","explanation":null,"wasCorrect":true},{"sid":"49402","title":"206. Que faut-il noter à la fin de l’administration 02 chez l’adulte ?","type":"mcq","input":"radio","multiple":false,"options":[{"text":"Le numéro de siège du passager","correct":false},{"text":"L’heure TU de fin d’administration","correct":true},{"text":"L’heure locale de décollage","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48904","title":"69. Choisissez la définition exacte de la cagoule de protection respiratoire","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"La cagoule protège les yeux et les voies respiratoires des gazs toxiques du Hafex et de la fumée. Elle est également certifiée pour protéger contre l’hypoxie après épuisement du circuit avion ou pour se déplacer en cabine","correct":true},{"text":"La cagoule protège les yeux des gaz toxiques du Hafex. Elle est également certifiée pour protéger contre l’hypoxie après épuisement du circuit avion ou pour se déplacer en cabine","correct":false},{"text":"La cagoule protège les yeux et les voies respiratoires des gaz toxiques du Hafex et de la fumée. Elle est également certifiée pour protéger contre l’asphyxie après épuisement du circuit avion ou pour se déplacer en cabine","correct":false},{"text":"La cagoule protège les yeux et les voies respiratoires des gaz toxiques du Hafex et de la fumée. Elle est également certifiée pour protéger contre l’hypoxie après épuisement du circuit avion mais ne permet pas les déplacements en cabine","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48989","title":"154. Quels apparaux sont dans le lot de survie additionnel ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Des bandes sol/air, des moyens pyrotechniques","correct":true},{"text":"Des moyens pyrotechniques, une écope, un dispositif de fonte de neige","correct":false},{"text":"5L d'eau potable par groupe de 50 PAX, un couteau, une pelle à neige","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48863","title":"28. A propos de l’utilisation du gilet adulte/enfant mono chambre, non réversible, sur un enfant, quel est l’ordre à respecter ?","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Passer le gilet, sangler, ajuster, gonfler","correct":false},{"text":"Passer le gilet, gonfler, sangler, ajuster","correct":true},{"text":"Passer le gilet, sangler, gonfler, ajuster","correct":false}],"description":null,"explanation":null,"wasCorrect":true},{"sid":"48947","title":"112. On utilise toujours toutes les bandes Sol/Air pour faire un seul signal","type":"mcq","input":"checkbox","multiple":false,"options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}],"description":null,"explanation":null,"wasCorrect":true}]}]};
